# Ejercicio T2-01 · El voto de los vecinos
# etiquetas es la lista con la clase de cada uno de los k vecinos más cercanos,
# por ejemplo ["defectuosa", "apta", "apta"]. Gana la clase que más se repite.

def votar(etiquetas):
    conteo = {}
    for e in etiquetas:
        conteo[e] = conteo.get(e, 0) + 1   # suma un voto a la clase e
    # conteo queda, por ejemplo, {"defectuosa": 1, "apta": 2}
    return etiquetas[0]   # ← cambia esta línea: devuelve la clase con más votos

# Pruébala con py run (o Ctrl+Enter). Debería imprimir apta:
print(votar(["defectuosa", "apta", "apta"]))
